<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;class UpbringingDashboard extends Page{protected static ?string $navigationIcon='heroicon-o-heart';protected static ?string $navigationLabel='Обзор отдела';protected static ?string $navigationGroup='Воспитательная работа';protected static ?int $navigationSort=1;protected static string $view='filament.pages.upbringing-dashboard';public array $stats=[];public function mount():void{$p=request()->attributes->get('academic_period');$pid=$p?->id;$q=fn($t)=>DB::table($t)->when($pid,fn($x)=>$x->where('academic_period_id',$pid));$this->stats=['planned'=>$q('upbringing_events')->where('status','planned')->count(),'done'=>$q('upbringing_events')->where('status','done')->count(),'cases'=>$q('student_support_cases')->where('status','open')->count(),'tasks'=>$q('upbringing_tasks')->where('status','!=','done')->count(),'achievements'=>$q('student_achievements')->count(),'appeals'=>$q('upbringing_appeals')->where('status','new')->count(),'overdue_cases'=>$q('student_support_cases')->where('status','!=','closed')->whereNotNull('next_contact_on')->where('next_contact_on','<',today())->count(),'overdue_tasks'=>$q('upbringing_tasks')->whereNotIn('status',['done','cancelled'])->whereNotNull('due_on')->where('due_on','<',today())->count(),'meetings'=>$q('parent_meetings')->count(),'commissions'=>$q('scholarship_commissions')->count()];}public static function canAccess():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->canDo('upbringing.view'));}}